import type { Bi } from "../i18n/registry";
import { UNKNOWN_STATES, type UnknownState } from "../core/types";
import type { AccessRule, ChoiceOption, FieldDef, FieldType, Importance, PrivacyClass, Purpose, Requirement } from "./types";

export const CATALOG_VERSION = 20;

const bi = (bn: string, en: string): Bi => ({ bn, en });
const opt = (code: string, bn: string, en: string): ChoiceOption => ({ code, label: bi(bn, en) });

interface Spec {
  id: string; entity: string; family: string; type: FieldType;
  label: Bi; what: Bi; why: Bi; example: Bi; format?: Bi;
  unit?: string; options?: ChoiceOption[];
  importance?: Importance; requirement?: Requirement; privacy?: PrivacyClass; purpose: Purpose;
  step?: number; affects?: string; unknown?: readonly UnknownState[];
}

/** Added to every Deen item: these are your own plans and reminders only (no scripture text, nothing counted or compared). D-D stays open. */
export const DEEN_NOTE: Bi = bi("শুধু আপনার প্ল্যান ও রিমাইন্ডার। কোনো ধর্মগ্রন্থের লেখা নেই; কিছু গোনা বা তুলনা করা হয় না।", "Plans and reminders only. No scripture text; nothing is counted or compared.");

function f(s: Spec): FieldDef {
  if (s.purpose === "deen_tracking") s = { ...s, why: bi(`${s.why.bn} ${DEEN_NOTE.bn}`, `${s.why.en} ${DEEN_NOTE.en}`) };
  const privacy = s.privacy ?? "personal";
  const access: AccessRule = privacy === "worship" || privacy === "health" ? "device_only_per_item_authorisation" : "device_only";
  return {
    id: s.id, entity: s.entity, family: s.family, type: s.type, unit: s.unit, options: s.options,
    label: s.label, help: { what: s.what, why: s.why, example: s.example, format: s.format },
    importance: s.importance ?? "useful", requirement: s.requirement ?? "optional",
    privacy, purpose: s.purpose, access,
    unknownStates: s.unknown ?? UNKNOWN_STATES,
    step: s.step ?? 0, affects: s.affects, retention: "until_user_deletes", offline: "local_only",
  };
}

